def signCount(nums):
    n = len(nums)

    def first_index(pred):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if pred(nums[mid]):
                hi = mid
            else:
                lo = mid + 1
        return lo

    negatives = first_index(lambda v: v >= 0)
    positives = n - first_index(lambda v: v > 0)
    return max(negatives, positives)
